* { box-sizing: border-box; }
:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #293b35;
  background: #f5e8c9;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background-color: #f5e8c9;
  background-image: linear-gradient(45deg, #ead9b2 25%, transparent 25%), linear-gradient(-45deg, #ead9b2 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #ead9b2 75%), linear-gradient(-45deg, transparent 75%, #ead9b2 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}
.card {
  width: min(100%, 460px);
  padding: 30px;
  border: 4px solid #293b35;
  border-radius: 8px;
  background: #fff9e9;
  box-shadow: 8px 8px 0 #293b35;
}
.header { text-align: center; }
.pixel-pot {
  position: relative;
  width: 52px;
  height: 34px;
  margin: 0 auto 19px;
  background: #d9794b;
  border: 4px solid #293b35;
  image-rendering: pixelated;
}
.pixel-pot::before, .pixel-pot::after {
  position: absolute;
  content: "";
  top: 8px;
  width: 8px;
  height: 10px;
  background: #fff9e9;
  border: 3px solid #293b35;
}
.pixel-pot::before { left: -13px; }
.pixel-pot::after { right: -13px; }
.pixel-pot span {
  position: absolute;
  width: 12px;
  height: 7px;
  left: 12px;
  top: -11px;
  border: 3px solid #293b35;
  border-bottom: 0;
}
.eyebrow { margin: 0 0 6px; color: #587066; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.6rem); line-height: 1.1; }
.intro { margin: 10px 0 26px; color: #587066; }
.converter label { display: block; margin-bottom: 9px; font-weight: 750; }
.inputs { display: flex; gap: 10px; }
input, select, button {
  min-height: 52px;
  border: 3px solid #293b35;
  border-radius: 5px;
  font: inherit;
}
input, select { background: #fff; color: #293b35; }
input { width: 40%; padding: 10px 12px; }
select { flex: 1; min-width: 0; padding: 10px; }
button {
  width: 100%; margin-top: 14px; padding: 11px 16px;
  color: #fff9e9; background: #587066; font-weight: 800; cursor: pointer;
  box-shadow: 0 4px 0 #293b35;
  transition: transform .08s ease, box-shadow .08s ease, background .15s ease;
}
button:hover { background: #405a50; }
button:active { transform: translateY(3px); box-shadow: 0 1px 0 #293b35; }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 4px solid #d9794b; outline-offset: 3px; }
.results { margin-top: 27px; }
h2 { margin: 0 0 12px; font-size: 1.15rem; }
#result-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
#result-list li { display: flex; justify-content: space-between; gap: 12px; padding: 11px 13px; border: 2px solid #d9cba9; background: #f5e8c9; }
#result-list strong { color: #405a50; font-variant-numeric: tabular-nums; }
footer { margin-top: 22px; padding-top: 16px; border-top: 2px dashed #d9cba9; color: #587066; text-align: center; font-size: .9rem; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 380px) { .card { padding: 23px 18px; } .inputs { gap: 7px; } select { padding-inline: 7px; } }

const form = document.getElementById('converter');
const amountInput = document.getElementById('amount');
const unitSelect = document.getElementById('unit');
const resultList = document.getElementById('result-list');

const units = [
  { key: 'cups', label: 'cups', perCup: 1 },
  { key: 'tbsp', label: 'tablespoons', perCup: 16 },
  { key: 'tsp', label: 'teaspoons', perCup: 48 },
  { key: 'ml', label: 'millilitres', perCup: 240 }
];

function renderResults() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.key === unitSelect.value);
  const cups = amount / source.perCup;
  resultList.replaceChildren(...units
    .filter((unit) => unit.key !== source.key)
    .map((unit) => {
      const item = document.createElement('li');
      const label = document.createElement('span');
      const value = document.createElement('strong');
      label.textContent = unit.label;
      value.textContent = `${(cups * unit.perCup).toFixed(1)} ${unit.key}`;
      item.append(label, value);
      return item;
    }));
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  renderResults();
});
amountInput.addEventListener('input', renderResults);
unitSelect.addEventListener('change', renderResults);
renderResults();
